﻿// OTHVM — Azkar (Aladhan API — no LLM). Full morning set after Fajr, full evening set after Asr.
const TZ = 'Africa/Cairo';
const LAT = 30.584138;
const LON = 31.495866;
const METHOD = 5;
const SCHOOL = 0;
const START_OFFSET_MIN = 10;
const WINDOW_MIN = 240;
const MAX_MSG_LEN = 3500;

const now = new Date();
const today = new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(now);
const nowHM = new Intl.DateTimeFormat('en-GB', { timeZone: TZ, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(now);
const toMin = (hm) => { const p = String(hm).split(':'); return Number(p[0]) * 60 + Number(p[1] || 0); };
const nowM = toMin(nowHM);

const sd = $getWorkflowStaticData('global');
if (!sd.sent || sd.sent.date !== today) sd.sent = { date: today, list: [] };
const already = (key) => sd.sent.list.indexOf(key) !== -1;
if (already('adhkar_morning') && already('adhkar_evening')) return [];

if (!sd.times || sd.times.date !== today) {
  const dmy = today.split('-').reverse().join('-');
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.aladhan.com/v1/timings/' + dmy + '?latitude=' + LAT + '&longitude=' + LON + '&method=' + METHOD + '&school=' + SCHOOL,
    json: true,
    timeout: 20000,
  });
  const t = res && res.data && res.data.timings ? res.data.timings : null;
  if (!t) return [];
  const clean = (v) => String(v || '').trim().split(' ')[0];
  sd.times = { date: today, list: {} };
  for (const key of ['Fajr', 'Asr']) sd.times.list[key] = clean(t[key]);
}

