  const yr = new Intl.DateTimeFormat('en-GB', { timeZone: TZ, year: 'numeric' }).format(now);
  dateStr = dn + ' ' + mo + ' ' + yr;
} catch (e) {
  dateStr = new Date(now.getTime() + 7200000).toISOString().slice(0, 10);
}
const fillDates = (t) => String(t).split('{date}').join(dateStr).split('{day}').join(wd);

const combineTexts = (texts) => {
  const messages = [];
  let current = '';
  for (const t of texts) {
    const ft = fillDates(t);
    if (current.length + ft.length + 2 > MAX_MSG_LEN) {
      if (current) messages.push(current);
      current = ft.length > MAX_MSG_LEN ? ft.slice(0, MAX_MSG_LEN) : ft;
    } else {
      current = current ? current + '

' + ft : ft;
    }
  }
  if (current) messages.push(current);
  return messages;
};

const ADHKAR = [
  { key: 'adhkar_morning', after: 'Fajr', texts: MORNING_TEXTS },
  { key: 'adhkar_evening', after: 'Asr', texts: EVENING_TEXTS },
];

const out = [];
for (const a of ADHKAR) {
  const base = sd.times.list[a.after];
  if (!base) continue;
  const startM = toMin(base) + START_OFFSET_MIN;
  if (nowM < startM || nowM > startM + WINDOW_MIN) continue;
  if (already(a.key)) continue;
  // Marked sent only after Telegram confirms delivery (Mark Sent node).
  const messages = combineTexts(a.texts);
  for (const m of messages) out.push({ json: { message: m, azkar: a.key } });
}

return out;

// OTHVM — mark Azkar as sent only after Telegram accepted every message.
// If Send Azkar fails, this node never runs and the next 5-minute tick retries.
const sd = $getWorkflowStaticData('global');
const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'Africa/Cairo', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
if (!sd.sent || sd.sent.date !== today) sd.sent = { date: today, list: [] };
for (const item of $('Build Azkar').all()) {
  const key = item.json && item.json.azkar;
  if (key && sd.sent.list.indexOf(key) === -1) sd.sent.list.push(key);
}
return [{ json: { ok: true, date: sd.sent.date, marked: sd.sent.list.slice() } }];
